buttonc_listitem_icon_simple_base.script:
function onValueChanged()
	local antimagicon = getValue();
	for _,v in pairs(UtilityManager.getTopWindow(window).list.getWindows()) do
		if antimagicon ~= v.activateantimagic.getValue() then
			v.activateantimagic.setValue(antimagicon);
		end
	end
end
